"""Build the six fixed EU campaign chapters from sourced local datasets."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'data/history/eu'
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
EU='https://european-union.europa.eu/principles-countries-history/'
COUNCIL='https://www.consilium.europa.eu/'
HIST=EU+'history-eu/'
BUD='https://commission.europa.eu/strategy-and-policy/eu-budget/long-term-eu-budget/2021-2027/spending-and-revenue_en'
REG='https://ec.europa.eu/eurostat/en/web/products-eurostat-news/w/ddn-20250211-2'
COH='https://cohesiondata.ec.europa.eu/stories/s/Outcome-of-2021-2027-programming-cohesion-policy/d6tf-zqvc/'
BREX=COUNCIL+'en/policies/the-eu-uk-withdrawal-agreement/'
MEM=EU+'eu-countries_en'
SCH=COUNCIL+'policies/schengen-area/'
ECB='https://www.ecb.europa.eu/press/pr/date/2026/html/ecb.pr260101~c830245e42.en.html'
ENL=COUNCIL+'en/topics/eu-enlargement/'
CUT=20261014
def view(c=[13,50],z=3):return {'mode':'globe','center':c,'zoom':z}
def scene(title,text,layers=(),center=[13,50],zoom=3,**kw):return {'title':title,'text':text,'view':view(center,zoom),'layers':list(layers),**kw}
def point(label,at,c='c3'):return {'at':at,'label':label,'r':4,'color':c}
def since(set='eu',year=CUT,color='c1',title=None):return {'type':'since','data':'memberships','set':set,'year':year,'color':color,'title':title or set.upper()+' · {n} countries'}
def timeline(years,start=None,date=True):return {'years':years,'start':start or years[0],**({'format':'date'}if date else {})}
def story(id,title,hook,scenes,data,refs,note=''):
 n='Editorial cutoff 14 October 2026. Original Orbis narrative and factual locators. '+note+' References by scene: '+' ; '.join(refs)
 write(ROOT/'stories'/(id+'.json'),{'id':id,'cat':'Geopolitics','title':title,'hook':hook,'updated':'2026-10-14','sources':['editorial']+(['eurostat']if id=='eu-regions'else[]),'notes':n,'data':data,'scenes':scenes})
members={'memberships':'data/history/eu/memberships.json'}
outline={'type':'shapes','data':'outline','year':CUT,'inner':False,'labels':False,'opacity':0.18}

growth=[
 scene('Coal and steel before the EU','Six governments signed the Coal and Steel treaty in 1951; it entered into force in 1952. France, West Germany, Italy and the Benelux countries began sharing institutions. Highlighted present-day countries locate those six participants; Germany’s modern outline is not its 1952 border.',[{'type':'categories','data':'memberships','set':'founders','colors':{'member':'c1'}}]),
 scene('Rome widens the project','The treaties signed in Rome in 1957 created the European Economic Community and Euratom, effective from January 1958. The map locates the same six participants and the treaty-signing city. Economic cooperation broadened without adding a new member at that moment.',[since(year=19580101,title='EEC · {n} participants')],points=[point('Rome',[12.5,41.9])]),
 scene('Northwest, then the Mediterranean','Denmark, Ireland and the United Kingdom joined in 1973, Greece in 1981, and Spain and Portugal in 1986. Step through the accession dates to see the membership geography spread. These are membership colours on today’s reference map, not historical sovereignty snapshots.',[since(year='t',title='European Communities · {n} members')],timeline=timeline([19730101,19810101,19860101])),
 scene('The union and another enlargement','The Maastricht Treaty entered into force in November 1993, creating the European Union. Austria, Finland and Sweden joined in January 1995. Compare membership before and after that enlargement: a treaty change and a membership change are different steps.',[since(year='t',title='EU · {n} members')],timeline=timeline([19931101,19950101])),
 scene('The eastern enlargement','Ten countries joined on 1 May 2004; Bulgaria and Romania followed in 2007, Croatia in July 2013. The timeline follows the resulting membership changes. Malta and Cyprus remind us that the 2004 wave extended beyond continental central and eastern Europe.',[since(year='t',title='EU · {n} members')],timeline=timeline([20040501,20070101,20130701])),
 scene('Twenty-seven at the cutoff','The United Kingdom left in 2020. At the 14 October 2026 cutoff the union has 27 members. This merged outer outline uses modern Natural Earth geometry; it shows the selected members together while hiding their internal lines, not a reconstruction of earlier European borders.',[outline],modernBorders=False)]
story('eu-growth','From the Coal and Steel Community to the EU','Membership grows in waves; institutions change on a different timetable.',growth,{**members,'outline':'data/history/eu/union-outline.json'},['Scenes 1-2: '+HIST+'1945-59_en','Scene 3: '+HIST+'1970-79_en and '+HIST+'1980-89_en','Scene 4: '+HIST+'1990-99_en','Scene 5: '+HIST+'2000-09_en and '+HIST+'2010-19_en','Scene 6: '+MEM+' ; '+BREX],'Modern country geometry only. West Germany joined the founding communities; current Germany is shown as a geographic locator. Overseas territories and treaty territorial exceptions are not depicted in detail.')

clubs=[
 scene('Three maps occupy the same space','EU membership, the euro and Schengen overlap, but they do not coincide. The crossing hatches show all three sets as of 14 October 2026. Schengen here means completed removal of internal land-border controls; temporary checks may still operate inside the area.',[{'type':'hatch','data':'memberships','sets':['eu','euro','schengen'],'year':CUT,'colors':{'eu':'c1','euro':'c2','schengen':'c4'},'labels':{'eu':'EU · {n}','euro':'Euro area · {n}','schengen':'Schengen · {n}'}}]),
 scene('Bulgaria changes currency','Bulgaria introduced the euro on 1 January 2026, becoming the euro area’s 21st member. Compare the area immediately before and after that date. Greece joined in 2001 and Croatia in 2023; euro adoption has its own timetable, separate from EU accession.',[since('euro','t','c2','Euro area · {n} members')],timeline=timeline([20251231,20260101,20261014])),
 scene('An opt-out and unfinished adoptions','Denmark has a treaty opt-out from adopting the euro. Czechia, Hungary, Poland, Romania and Sweden have not adopted it, but have no equivalent euro opt-out. Colours distinguish that legal difference among EU members at the cutoff.',[{'type':'categories','data':'memberships','set':'euro_status','year':CUT,'colors':{'euro':'c2','optout':'c3','notyet':'c1'}}]),
 scene('Schengen reaches the eastern land borders','Bulgaria and Romania entered the air/sea-control-free area in March 2024. Their remaining internal land checks were removed on 1 January 2025. This bounded timeline shows full land-border participation, so the two countries appear only at that final step.',[since('schengen','t','c4','Full Schengen land participation · {n}')],timeline=timeline([20240101,20250101,20261014])),
 scene('Inside one club, outside another','Ireland belongs to the EU and euro area but not Schengen; Cyprus’s internal controls have not yet been lifted. Norway, Iceland, Switzerland and Liechtenstein are in Schengen without EU membership. Switch the highlighted set to see those contrasts rather than treating Europe as one uniform border regime.',[since('{set}',CUT,'{color}','{label} · {n}')],switch={'label':'Compare membership','options':[{'set':'eu','color':'c1','label':'EU'},{'set':'euro','color':'c2','label':'Euro'},{'set':'schengen','color':'c4','label':'Schengen'}]})]
story('eu-clubs','Euro, Schengen and opt-outs','Overlapping memberships explain why one European border map is insufficient.',clubs,members,['Scenes 1,4-5: '+SCH+' ; '+COUNCIL+'en/press/press-releases/2024/12/12/schengen-council-decides-to-lift-land-border-controls-with-bulgaria-and-romania/','Scene 2: '+ECB+' ; '+MEM,'Scene 3: https://european-union.europa.eu/institutions-law-budget/euro/countries-using-euro_en'],'The Schengen dataset starts with a 1 January 2024 observation, not each country’s original accession date. Country status is illustrated on modern base geometry; special territorial applications, suspended acquis and temporary internal checks are not rendered as control areas.')

def bmap(series,year=2025,**kw):return {'type':'choropleth','data':'budget','series':series,'year':year,'fmt':'d3:,.0f',**kw}
def bchart(series,title,year=2025):return {'data':'budget','series':series,'year':year,'title':title+' (EUR million)','fmt':'d3:,.0f','top':6,'color':'c1'}
budget=[
 scene('Who finances the budget','In the Commission’s 2025 country data, Germany supplies about €29 billion in VAT/GNI/plastics financing including adjustments, with customs excluded. France follows at about €23 billion. The map and chart use that defined financing measure, rather than treating customs collected at ports as a national contribution.',[bmap('financing',title='Defined financing, EUR million')],chart=bchart('financing','2025 financing, customs excluded')),
 scene('Where spending is allocated','Country-allocated ordinary spending and NextGenerationEU are separate parts of the Commission workbook. Switch between them, then their sum. In 2025 Italy’s combined allocation is about €23 billion. These nominal expenditure figures include administration; their geographic allocation is an accounting convention.',[bmap('{series}',title='{label}, EUR million')],chart=bchart('{series}','{label}'),switch={'label':'Allocated expenditure','options':[{'series':'ordinary','label':'Ordinary'},{'series':'ngeu','label':'NGEU'},{'series':'receipts','label':'Combined'}]}),
 scene('Two sides of a defined cash comparison','Subtract the defined financing measure from country-allocated expenditure including NGEU. In 2025 Germany is about €16 billion below its financing, while Poland is about €9 billion above. The signed map and switched charts show this arithmetic; it is not the Commission’s operating budgetary balance.',[bmap('difference',title='Expenditure minus financing, EUR million',diverging=True,mid=0,vmin=-17000,vmax=17000)],chart=bchart('{side}','{label}'),switch={'label':'Show positive magnitudes','options':[{'side':'surplus','label':'Spending exceeds financing'},{'side':'excess','label':'Financing exceeds spending'}]}),
 scene('A year changes the picture','Move through 2021–2025. Ordinary budgets, recovery spending and adjustments change the country allocations from year to year. The map holds one colour scale for the defined expenditure-minus-financing difference. A one-year cash difference does not describe the long-term value of EU membership.',[bmap('difference','t',title='Expenditure minus financing, EUR million',diverging=True,mid=0,vmin=-25000,vmax=25000)],timeline=timeline([2021,2025],date=False)),
 scene('Administrative geography matters','Belgium and Luxembourg host EU institutions. In this 2025 definition their country-allocated spending exceeds financing. The Commission warns that geographic allocation is imperfect and expenditure can benefit several countries. Brussels and Luxembourg locate institutional centres; a positive balance is not a transfer into every resident’s household.',[bmap('difference',title='Defined difference, EUR million',diverging=True,mid=0,vmin=-17000,vmax=17000)],center=[5,50],zoom=5,points=[point('Brussels',[4.35,50.85]),point('Luxembourg',[6.13,49.61])])]
story('eu-budget','Who pays and who receives','Compare a defined financing measure with ordinary and recovery expenditure.',budget,{'budget':'data/history/eu/budget.json'},['All scenes and numerical claims: '+BUD,'Scene 5 institutional geography: '+EU+'eu-countries/belgium_en and '+EU+'eu-countries/luxembourg_en'],'European Commission workbook 2000–2025 released 29 September 2026; Orbis subset and derived differences, CC BY 4.0. All charts show EUR million. Financing = own resources plus balances/adjustments minus customs. Spending = ordinary country expenditure plus country NGEU. Neither benefits of the single market nor household income can be inferred. Country sums reconcile to workbook EU27 allocation columns; do not compare country spending with the larger total containing earmarked/unallocated/non-EU amounts.')

regional=[
 scene('Regions differ inside the same union','In Eurostat’s February 2025 release of 2023 NUTS 2 data, Eastern and Midland Ireland has GDP per inhabitant of 244.7% of the EU average. Yuzhen Tsentralen in Bulgaria is at 41.3%. Regional reference symbols and the chart compare the same indicator; symbol area follows its value, not a city GDP reading.',[{'type':'symbols','data':'regions','field':'gdp','period':'2023','labels':0,'maxR':10,'vmax':250,'title':'Selected regional GDP/head, EU27=100','fmt':'d3:.1f'}],chart={'data':'regions','field':'gdp','period':'2023','title':'Selected NUTS2 GDP/head, EU27=100','fmt':'d3:.1f','top':8}),
 scene('A capital and a lower-output region','Praha reaches 192.8% of the EU average while Yuzhen Tsentralen reaches 41.3% in that same release. The highlighted reference places locate whole statistical regions. The comparison crosses countries and uses one observation year and unit; it does not compare municipal incomes.',[],center=[19.5,46.5],zoom=4,points=[point('Praha · 192.8',[14.42,50.08]),point('Yuzhen Tsentralen · 41.3',[24.75,42.14])]),
 scene('Cohesion has a regional rule','For 2021–2027, cohesion policy distinguishes less developed regions below 75% of EU-average GDP per head, transition regions from 75% to 100%, and more developed regions above 100%. These selected regions locate the question the policy addresses. Their 2023 values do not retroactively determine official 2021–2027 eligibility.',[],points=[point('Praha',[14.42,50.08]),point('Yuzhen Tsentralen',[24.75,42.14])]),
 scene('Money crosses into cohesion programmes','The Commission’s 2025 ordinary-budget allocation for economic, social and territorial cohesion is about €7.1 billion in Poland and €3.2 billion in Italy. This is a country-level funding view beside the regional comparisons. It excludes separate NGEU allocations and does not assign every national euro to a particular region.',[bmap('cohesion',title='Ordinary cohesion allocation, EUR million')],chart=bchart('cohesion','Country cohesion spending')),
 scene('Output is not a household pay cheque','Eurostat warns that commuting workers and multinational enterprises help explain very high regional GDP per inhabitant. Brussels and the Irish regions illustrate that issue. Read the GDP comparison alongside the funding definitions: both describe geographic accounting units, not the earnings of a typical family.',[],center=[-1,52],zoom=4,points=[point('Brussels',[4.35,50.85]),point('Eastern and Midland',[ -6.3,53.35]),point('Southern Ireland',[-8.47,51.90])])]
story('eu-regions','Cohesion money and regions','Regional output contrasts with the geography of cohesion spending.',regional,{'regions':'data/history/eu/regions.json','budget':'data/history/eu/budget.json'},['Scenes 1-2,5: '+REG,'Scene 3: '+COH+' ; https://ec.europa.eu/eurostat/en/web/regions/information-data/policy-context','Scene 4: '+BUD],'Approved fallback: sourced regional comparison chart and located reference symbols instead of imported NUTS polygons. Eurostat 2023 comparison frozen to its 11 February 2025 publication. Selected regions, not a complete regional rank; overseas regions omitted. CC BY 4.0; Orbis selected subset/reference locations; Eurostat is not responsible for these modifications. National 2025 cohesion expenditure and regional 2023 GDP are separate datasets and units; no regional spending allocation is invented.')

events=[{'title':'UK referendum','date':20160623,'at':[-0.12,51.51],'kind':'brexit','text':'UK valid-vote totals: Leave 17,410,742; Remain 16,141,241. Leave share is 51.89%, calculated from those official totals. London is a national institutional locator, not the result announcement site.','source':'UK Electoral Commission; Orbis summary','url':'https://www.electoralcommission.org.uk/research-reports-and-data/our-reports-and-data-past-elections-and-referendums/results-and-turnout-eu-referendum'},{'title':'Article 50 notification','date':20170329,'at':[4.35,50.85],'kind':'brexit','text':'The UK formally notified the European Council of its intention to leave on 29 March 2017.','source':'Council of the EU; Orbis summary','url':BREX},{'title':'UK departure takes effect','date':20200201,'at':[-0.12,51.51],'kind':'brexit','text':'Departure occurred at midnight CET on 31 January 2020; the withdrawal agreement entered into force on 1 February.','source':'Council of the EU; Orbis summary','url':BREX},{'title':'Transition ends','date':20201231,'at':[4.35,50.85],'kind':'brexit','text':'The withdrawal agreement transition period ran to 31 December 2020.','source':'Council of the EU; Orbis summary','url':BREX}]
write(OUT/'brexit-events.json',{'source':'editorial','asOf':'2020-12-31','retrieved':'2026-10-14','note':'Original factual annotations and approximate city locators, not source prose or movements. Each card links primary evidence.','kinds':{'brexit':{'label':'Withdrawal timeline','color':'c2'}},'items':events})
brexit=[
 scene('The vote came before the departure','The UK voted in June 2016 to leave, with about 52% of valid votes for Leave. Article 50 notification followed in March 2017. Step between the two cards: neither date itself removed the UK from membership. London and Brussels locate the institutional relationship.',[{'type':'cards','data':'events','year':'t','list':True,'labels':False}],center=[0,52],zoom=4,timeline=timeline([20160623,20170329]),points=[point('London',[-0.12,51.51]),point('Brussels',[4.35,50.85])]),
 scene('The referendum had regional contrasts','The Electoral Commission’s official totals give Remain about 62% in Scotland and 56% in Northern Ireland. London also voted Remain. Edinburgh, Belfast and London locate these reporting areas; the dots are not ward-level results or a claim that everyone in each area voted alike.',[],center=[-3,55],zoom=5,points=[point('Scotland / Edinburgh',[-3.19,55.95],'c4'),point('Northern Ireland / Belfast',[-5.93,54.6],'c4'),point('London',[-0.12,51.51],'c4')]),
 scene('One member leaves the set','At midnight CET on 31 January 2020 the UK left. This day-based timeline switches membership on 1 February, following the withdrawal agreement’s entry into force. Compare the highlighted set before and after that instant: the EU changes from 28 members to 27.',[since(year='t',title='EU · {n} members')],center=[4,52],zoom=3,timeline=timeline([20200131,20200201,20201231])),
 scene('An island creates a special border problem','The withdrawal agreement and Windsor Framework aim to avoid a hard border on the island of Ireland. Northern Ireland remains part of the UK, while Ireland is an EU member. The paired locators show the island’s two jurisdictions; no checkpoint locations or customs routes are asserted.',[],center=[-7,54],zoom=6,points=[point('Belfast',[-5.93,54.6]),point('Dublin',[-6.26,53.35])],highlight=['IRL','GBR']),
 scene('Institutions also move','The European Medicines Agency moved from London to Amsterdam, and the European Banking Authority to Paris. The Council’s account links those relocations to withdrawal. The three city markers show where institutional seats changed; the financial settlement and future relationship continued beyond formal departure.',[],center=[2,51],zoom=5,points=[point('London',[-0.12,51.51]),point('Amsterdam',[4.90,52.37]),point('Paris',[2.35,48.86])])]
story('eu-brexit','Brexit','A vote, a notification, a withdrawal and a new border arrangement.',brexit,{**members,'events':'data/history/eu/brexit-events.json'},['Scenes 1-2: https://www.electoralcommission.org.uk/research-reports-and-data/our-reports-and-data-past-elections-and-referendums/results-and-turnout-eu-referendum','Scenes 1,3-5: '+BREX],'Event cards use original factual annotations. Rounded vote shares come from official valid-vote totals. Country membership uses Gregorian dates; present-day country geometry is context. Institutional seats are locators, not mover routes.')

candidates=[
 scene('Candidates surround the union','The Council lists nine candidate countries at this 14 October 2026 cutoff: Albania, Bosnia and Herzegovina, Georgia, Moldova, Montenegro, North Macedonia, Serbia, Turkey and Ukraine. Their colour denotes candidate status alone. It does not guarantee accession or show a ranking of progress.',[{'type':'categories','data':'memberships','set':'candidates','colors':{'candidate':'c3'}}],center=[25,45],zoom=3),
 scene('The Western Balkans','Albania, Bosnia and Herzegovina, Montenegro, North Macedonia and Serbia are candidates. Kosovo has applied but is not listed as a candidate. These are different procedural statuses; the map’s Kosovo geometry follows the base map and does not settle the dispute over recognition.',[{'type':'categories','data':'memberships','set':'candidates','colors':{'candidate':'c3'}}],center=[20,43],zoom=5,points=[point('Kosovo: applicant',[21.16,42.66],'muted')]),
 scene('Ukraine and Moldova move through negotiations','The EU held accession conferences with Ukraine, Moldova, Montenegro and Albania on 14 July 2026. The Council described the Ukraine and Moldova conferences as opening the external-relations cluster. The highlighted candidates are part of an active negotiating process, not already members.',[],center=[29,48],zoom=4,highlight=['UKR','MDA'],fills={'UKR':'c3','MDA':'c3'}),
 scene('Candidate status can coexist with a halt','The Council describes Turkey’s accession negotiations as effectively at a standstill since June 2018 and Georgia’s process as de facto halted in 2024. Both remain on its candidate list. Candidate colour must therefore be read separately from the state of negotiations.',[],center=[36,42],zoom=4,highlight=['TUR','GEO'],fills={'TUR':'c5','GEO':'c5'}),
 scene('Accession requires more than geography','The Copenhagen criteria concern institutions, rights, economic capacity and the implementation of EU law. Completing negotiations leads to an accession treaty requiring approval and ratification. The union outline and the candidate colours show the institutional geography at the cutoff; proximity alone does not determine admission.',[outline,{'type':'categories','data':'memberships','set':'candidates','colors':{'candidate':'c3'}}],modernBorders=False)]
story('eu-candidates','Candidates and enlargement','Candidate status, active negotiations and stalled paths occupy different maps.',candidates,{**members,'outline':'data/history/eu/union-outline.json'},['Scenes 1-2: '+ENL,'Scene 3: '+COUNCIL+'en/press/news/20260714-four-accession-conferences-in-one-day/','Scene 4: '+COUNCIL+'en/policies/turkiye/ and '+COUNCIL+'en/policies/georgia/','Scene 5: '+COUNCIL+'en/policies/how-enlargement-works/'],'Status snapshot verified from official Council pages on 14 October 2026; negotiations scene uses a named 14 July 2026 event. Country categories do not imply recognized borders, occupation control or an accession forecast.')
print('Built six EU chapters (31 substantive scenes).')
